                        .contentType(MediaType.APPLICATION_JSON)
                        .content("""
                                {"requestId":"nf-2","expectedVersion":1,"cumulativeMinutes":10}
                                """))
                .andExpect(status().isNotFound());
        mockMvc.perform(get("/api/equipment/eq-nf/readings/nope/revisions"))
                .andExpect(status().isNotFound());
    }
