    @Test
    void apply_invalidParams_badRequest() throws Exception {
        register("eq-d3", 100);
        // 分钟数下限 1
        mockMvc.perform(post("/api/equipment/eq-d3/deferrals")
                        .contentType(MediaType.APPLICATION_JSON)
